package scripts

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The Gradle project is regenerated by `cargo tauri android init`, which
// writes a bare MainActivity. Edge-to-edge (forced from targetSdk 35) then
// draws the WebView under the system bars, so guard the insets handling.
func TestAndroidMainActivityPadsContentBySystemInsets(t *testing.T) {
	path := filepath.Join(repositoryRoot(t), "desktop", "src-tauri", "gen", "android", "app",
		"src", "main", "java", "app", "tariboy", "desktop", "MainActivity.kt")
	source, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"enableEdgeToEdge()",
		"ViewCompat.setOnApplyWindowInsetsListener(findViewById(android.R.id.content))",
		"WindowInsetsCompat.Type.systemBars()",
		"WindowInsetsCompat.Type.displayCutout()",
		"WindowInsetsCompat.Type.ime()",
		".setPadding(",
	} {
		if !strings.Contains(string(source), want) {
			t.Errorf("MainActivity.kt does not contain %q", want)
		}
	}
	// Below Android 11 the keyboard reports its insets only in adjustResize.
	manifest, err := os.ReadFile(filepath.Join(filepath.Dir(path), "..", "..", "..", "..",
		"AndroidManifest.xml"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(manifest), `android:windowSoftInputMode="adjustResize"`) {
		t.Error(`AndroidManifest.xml does not set android:windowSoftInputMode="adjustResize"`)
	}
}
